import Foundation

/// Developer test set for the AI router (see docs/ROUTER_TEST_SET.md, generated
/// from the same list). Phrases today's keyword rules miss or get wrong.
struct RouterTestCase {
    let language: String
    let flags: RouterFlags
    let expected: HybridRoute
    let text: String
}

